import base64
from taf.internal.cloud.lcmaas.client.lcmaas.v1 import (DppsApi, DppIn, CnfInstanceIn,
                                                        HelmChartOverride, DppPatch, CnfInstancePatch)


class DPPv1(object):
    def __init__(self, api_client):
        self.dpp_api_v1 = DppsApi(api_client=api_client)

    def get_dpps(self, group=None):
        return self.dpp_api_v1.get_dpps(group=group)

    def get_dpp_by_name(self, dpp_name):
        return self.dpp_api_v1.get_dpp_by_name(dpp_name=dpp_name)

    def create_dpp(self, dpp_name, cnf_pkg_name, cnf_instance_name, vi_name, namespace,
                   chart_override_mapping=None, dpp_group=None):
        overrides_list = []
        if chart_override_mapping:
            for override in chart_override_mapping:
                helm_chart_override = HelmChartOverride(chart=list(override.keys())[0],
                                                        override_value=self._change_file_to_base64(list(override.values())[0]))
                overrides_list.append(helm_chart_override)

        cnf_instance_data = CnfInstanceIn(name=cnf_instance_name,
                                          vi=vi_name,
                                          overrides=overrides_list)
        create_dpp_data = DppIn(name=dpp_name, group=dpp_group, cnf_package=cnf_pkg_name,
                                cnf_instance=cnf_instance_data, namespace=namespace)
        return self.dpp_api_v1.create_dpp(dpp_in=create_dpp_data)

    def delete_dpp(self, dpp_name):
        return self.dpp_api_v1.delete_dpp_by_name(dpp_name=dpp_name)

    def update_dpp(self, dpp_name, cnfpkg_name=None, chart_override_mapping=None):
        chart_override_list = []
        if chart_override_mapping:
            for override in chart_override_mapping:
                helm_chart_override = HelmChartOverride(chart=list(override.keys())[0],
                                                        override_value=self._change_file_to_base64(list(override.values())[0]))
                chart_override_list.append(helm_chart_override)

        cnf_instance_data = CnfInstancePatch(overrides=chart_override_list)
        dpp_patch_data = DppPatch(cnf_package=cnfpkg_name, cnf_instance=cnf_instance_data)
        return self.dpp_api_v1.update_dpp_by_name(dpp_name=dpp_name,
                                                  dpp_patch=dpp_patch_data)

    @staticmethod
    def _change_file_to_base64(input_file):
        with open(input_file) as file_obj:
            content = file_obj.read()
        base64_data = base64.b64encode(content.encode(encoding='utf-8')).decode()
        return base64_data
